#!/usr/bin/env python3
"""Offline auditor for a synthetic QUIC v1 receiver model.

Reads one JSON document on stdin, replays every trace through the finite
receiver state machine described in the task contract and writes one JSON
document on stdout.
"""
import sys
import json
import re
import bisect

MAXN = 4611686018427387903          # 2**62 - 1
MAXT = 1000000000000                # event timestamp domain
LIM_TRACES = 32
LIM_EVENTS = 20000
LIM_PACKETS = 20000
LIM_FRAMES = 60000
LIM_DATA = 2 * 1024 * 1024
LIM_HEXCHUNK = 4096                 # 2048 bytes -> 4096 hex chars
LIM_RANGES = 32
LIM_DG_PKTS = 16
LIM_PKT_FRAMES = 64

INVALID_OUT = '{"error":"INVALID_INPUT"}'

LEVELS = ("I", "H", "Z", "A")
# packet number space of each level (Z shares the Application set)
SPACE_OF = {"I": "I", "H": "H", "Z": "A", "A": "A"}

# frame tag -> set of levels where the frame is permitted by the whitelist
ALLOWED = {
    "pad": ("I", "H", "Z", "A"),
    "ping": ("I", "H", "Z", "A"),
    "ack": ("I", "H", "A"),
    "cry": ("I", "H", "A"),
    "str": ("Z", "A"),
    "rs": ("Z", "A"),
    "ss": ("Z", "A"),
    "cl0": ("I", "H", "Z", "A"),   # CLOSE with app == false
    "cl1": ("Z", "A"),             # CLOSE with app == true
    "hd": (),                      # receiver is a server
}


class Bad(Exception):
    """Raised for every invalid input."""


ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")
HEX_RE = re.compile(r"[0-9a-f]*\Z")
WS_RE = re.compile(r"[ \t\n\r]*\Z")
JSON_WS = " \t\n\r"


# --------------------------------------------------------------------------
# validation
# --------------------------------------------------------------------------

def _pairs_hook(pairs):
    obj = {}
    for k, v in pairs:
        if k in obj:
            raise Bad()
        obj[k] = v
    return obj


def _reject_const(_name):
    raise Bad()


DECODER = json.JSONDecoder(parse_constant=_reject_const,
                           object_pairs_hook=_pairs_hook)


def _is_int(v):
    return type(v) is int


def _is_domain_int(v):
    return type(v) is int and 0 <= v <= MAXN


def _keys_exact(obj, required):
    if type(obj) is not dict:
        raise Bad()
    if len(obj) != len(required):
        raise Bad()
    for k in required:
        if k not in obj:
            raise Bad()
    return obj


def _need(cond):
    if not cond:
        raise Bad()


def _parse_ranges_grammar(v):
    """ACK frame ranges: shape/domain/length only (ordering is a protocol matter)."""
    if type(v) is not list:
        raise Bad()
    if len(v) > LIM_RANGES:
        raise Bad()
    out = []
    for item in v:
        if type(item) is not list or len(item) != 2:
            raise Bad()
        lo = item[0]
        hi = item[1]
        if not _is_domain_int(lo) or not _is_domain_int(hi):
            raise Bad()
        out.append((lo, hi))
    return out


def _parse_ranges_cfg(v):
    """CONFIG ranges: also low<=high, ascending, disjoint, nonadjacent."""
    out = _parse_ranges_grammar(v)
    prev_hi = None
    for lo, hi in out:
        if lo > hi:
            raise Bad()
        if prev_hi is not None and lo <= prev_hi + 1:
            raise Bad()
        prev_hi = hi
    return out


def _parse_data_hex(v, counts):
    if type(v) is not str:
        raise Bad()
    n = len(v)
    if n > LIM_HEXCHUNK or (n & 1):
        raise Bad()
    if not HEX_RE.match(v):
        raise Bad()
    data = bytes.fromhex(v)
    counts[3] += len(data)
    if counts[3] > LIM_DATA:
        raise Bad()
    return data


def _parse_frame(f, counts):
    if type(f) is not dict:
        raise Bad()
    ty = f.get("type")
    if type(ty) is not str:
        raise Bad()
    if ty == "PADDING":
        _keys_exact(f, ("type",))
        return ("pad",)
    if ty == "PING":
        _keys_exact(f, ("type",))
        return ("ping",)
    if ty == "UNKNOWN":
        _keys_exact(f, ("type",))
        return ("un",)
    if ty == "HANDSHAKE_DONE":
        _keys_exact(f, ("type",))
        return ("hd",)
    if ty == "ACK":
        _keys_exact(f, ("type", "ranges"))
        return ("ack", tuple(_parse_ranges_cfg_grammar(f["ranges"])))
    if ty == "CRYPTO":
        _keys_exact(f, ("type", "offset", "data_hex"))
        off = f["offset"]
        if not _is_domain_int(off):
            raise Bad()
        return ("cry", off, _parse_data_hex(f["data_hex"], counts))
    if ty == "STREAM":
        _keys_exact(f, ("type", "id", "offset", "data_hex", "fin"))
        sid = f["id"]
        off = f["offset"]
        if not _is_domain_int(sid) or not _is_domain_int(off):
            raise Bad()
        if type(f["fin"]) is not bool:
            raise Bad()
        return ("str", sid, off, _parse_data_hex(f["data_hex"], counts), f["fin"])
    if ty == "RESET_STREAM":
        _keys_exact(f, ("type", "id", "final_size"))
        sid = f["id"]
        size = f["final_size"]
        if not _is_domain_int(sid) or not _is_domain_int(size):
            raise Bad()
        return ("rs", sid, size)
    if ty == "STOP_SENDING":
        _keys_exact(f, ("type", "id"))
        sid = f["id"]
        if not _is_domain_int(sid):
            raise Bad()
        return ("ss", sid)
    if ty == "CLOSE":
        _keys_exact(f, ("type", "app", "code"))
        if type(f["app"]) is not bool:
            raise Bad()
        code = f["code"]
        if not _is_domain_int(code):
            raise Bad()
        return ("cl", f["app"], code)
    raise Bad()


def _parse_ranges_cfg_grammar(v):
    # ACK frame ranges keep the grammar-level checks only.
    return _parse_ranges_grammar(v)


def _parse_packet(p, counts):
    if type(p) is not dict:
        raise Bad()
    _keys_exact(p, ("level", "pn", "auth", "frames"))
    lvl = p["level"]
    if type(lvl) is not str or lvl not in LEVELS:
        raise Bad()
    if not _is_domain_int(p["pn"]):
        raise Bad()
    if type(p["auth"]) is not bool:
        raise Bad()
    frames = p["frames"]
    if type(frames) is not list or len(frames) > LIM_PKT_FRAMES:
        raise Bad()
    counts[1] += 1
    if counts[1] > LIM_PACKETS:
        raise Bad()
    out = []
    for fr in frames:
        counts[2] += 1
        if counts[2] > LIM_FRAMES:
            raise Bad()
        out.append(_parse_frame(fr, counts))
    return (lvl, SPACE_OF[lvl], p["pn"], p["auth"], tuple(out))


def _parse_event(e, counts, prev_t):
    if type(e) is not dict:
        raise Bad()
    ty = e.get("op")
    if type(ty) is not str:
        raise Bad()
    if "t" not in e:
        raise Bad()
    t = e["t"]
    if type(t) is not int or t < 0 or t > MAXT or t < prev_t:
        raise Bad()
    if ty == "tick":
        _keys_exact(e, ("t", "op"))
        counts[0] += 1
        return ("tk", t)
    if ty == "key":
        _keys_exact(e, ("t", "op", "level", "action"))
        lvl = e["level"]
        act = e["action"]
        if type(lvl) is not str or lvl not in LEVELS:
            raise Bad()
        if act != "install" and act != "discard":
            raise Bad()
        counts[0] += 1
        return ("k", t, lvl, act)
    if ty == "datagram":
        _keys_exact(e, ("t", "op", "bytes", "packets"))
        size = e["bytes"]
        if type(size) is not int or size < 0 or size > 65535:
            raise Bad()
        pkts = e["packets"]
        if type(pkts) is not list or not (1 <= len(pkts) <= LIM_DG_PKTS):
            raise Bad()
        parsed = tuple(_parse_packet(p, counts) for p in pkts)
        counts[0] += 1
        return ("dg", t, size, parsed)
    raise Bad()


def _parse_config(c):
    cfg = _keys_exact(c, ("early", "overlap", "buffer_packets", "idle_ms",
                          "max_streams_bidi", "max_streams_uni",
                          "max_stream_data", "max_data", "crypto_limit",
                          "sent"))
    early = cfg["early"]
    if type(early) is not bool:
        raise Bad()
    ov = cfg["overlap"]
    if ov != "reject" and ov != "first":
        raise Bad()
    _need_bounded_int(cfg["buffer_packets"], 1024)
    _need_bounded_int(cfg["idle_ms"], 1000000000)
    _need_bounded_int(cfg["max_streams_bidi"], 1024)
    _need_bounded_int(cfg["max_streams_uni"], 1024)
    _need_bounded_int(cfg["max_stream_data"], 65536)
    _need_bounded_int(cfg["max_data"], MAXN)
    _need_bounded_int(cfg["crypto_limit"], 65536)
    sent = _keys_exact(cfg["sent"], ("I", "H", "A"))
    out = {}
    for lvl in ("I", "H", "A"):
        rngs = _parse_ranges_cfg(sent[lvl])
        out[lvl] = (tuple(r[0] for r in rngs), tuple(rngs))
    return {
        "early": early,
        "reject": ov == "reject",
        "buffer_packets": cfg["buffer_packets"],
        "idle_ms": cfg["idle_ms"],
        "max_streams_bidi": cfg["max_streams_bidi"],
        "max_streams_uni": cfg["max_streams_uni"],
        "max_stream_data": cfg["max_stream_data"],
        "max_data": cfg["max_data"],
        "crypto_limit": cfg["crypto_limit"],
        "sent": out,
    }


def _need_bounded_int(v, hi):
    if type(v) is not int or v < 0 or v > hi:
        raise Bad()


def _parse_trace(tr, counts):
    t = _keys_exact(tr, ("id", "config", "events"))
    tid = t["id"]
    if type(tid) is not str or not ID_RE.match(tid):
        raise Bad()
    cfg = _parse_config(t["config"])
    events = t["events"]
    if type(events) is not list:
        raise Bad()
    out = []
    prev_t = 0
    for e in events:
        ev = _parse_event(e, counts, prev_t)
        prev_t = ev[1]
        out.append(ev)
    return (tid, cfg, tuple(out))


def parse_request(text):
    """Return the list of validated traces, raising Bad on any violation."""
    m = WS_RE.match(text)          # only used for the empty-document case
    if not text:
        raise Bad()
    obj = json.loads(text, parse_constant=_reject_const,
                     object_pairs_hook=_pairs_hook)
    root = _keys_exact(obj, ("version", "traces"))
    if not _is_int(root["version"]) or root["version"] != 1:
        raise Bad()
    traces = root["traces"]
    if type(traces) is not list:
        raise Bad()
    if len(traces) > LIM_TRACES:
        raise Bad()
    counts = [0, 0, 0, 0]          # events, packets, frames, decoded bytes
    seen_ids = set()
    out = []
    for tr in traces:
        tid, cfg, events = _parse_trace(tr, counts)
        if counts[0] > LIM_EVENTS:
            raise Bad()
        if tid in seen_ids:
            raise Bad()
        seen_ids.add(tid)
        out.append((tid, cfg, events))
    return out


# --------------------------------------------------------------------------
# byte range bookkeeping
# --------------------------------------------------------------------------

def store_insert(ivs, a, data, reject, journal):
    """Store data at [a, a+len(data)) into the disjoint interval list ivs.

    Existing bytes always win (the model never overwrites), so a differing
    overlap is reported as a conflict when the policy is 'reject'.
    Returns False on a rejected conflict, True when something was stored and
    None when the range was already fully covered.
    """
    n = len(data)
    if n == 0:
        return None
    b = a + n
    i0 = bisect.bisect_left(ivs, (a,))
    if i0 > 0 and ivs[i0 - 1][1] > a:
        i0 -= 1
    i = i0
    end = len(ivs)
    covered = []
    while i < end:
        s = ivs[i][0]
        if s >= b:
            break
        e = ivs[i][1]
        d = ivs[i][2]
        lo = s if s > a else a
        hi = e if e < b else b
        if d[lo - s:hi - s] != data[lo - a:hi - a]:
            if reject:
                return False
        covered.append((lo, hi))
        i += 1
    gaps = []
    pos = a
    for lo, hi in covered:
        if lo > pos:
            gaps.append((pos, lo, data[pos - a:lo - a]))
        pos = hi
    if b > pos:
        gaps.append((pos, b, data[pos - a:b - a]))
    if not gaps:
        return None
    # merge the new gaps with the existing intervals in [i0, i)
    merged = []
    j = i0
    k = 0
    ng = len(gaps)
    while j < i or k < ng:
        if k >= ng or (j < i and ivs[j][0] < gaps[k][0]):
            merged.append(ivs[j])
            j += 1
        else:
            merged.append(gaps[k])
            k += 1
    journal.append((ivs, i0, i, ivs[i0:i], merged))
    ivs[i0:i] = merged
    return True


def store_deliver(ivs, pos):
    """Return (bytes, new_pos) for the contiguous run starting at pos."""
    idx = bisect.bisect_left(ivs, (pos,))
    if idx > 0 and ivs[idx - 1][1] > pos:
        idx -= 1
    out = None
    n = len(ivs)
    end = len(ivs)
    while idx < end:
        s, e, d = ivs[idx]
        if s > pos:
            break
        if e > pos:
            if out is None:
                out = [d[pos - s:e - s]]
            else:
                out.append(d[pos - s:e - s])
            pos = e
        idx += 1
    if out is None:
        return None, pos
    if len(out) == 1:
        return out[0], pos
    return b"".join(out), pos


# --------------------------------------------------------------------------
# replay
# --------------------------------------------------------------------------

class Stream(object):
    __slots__ = ("sid", "highest", "final", "reset", "stopped", "ivs",
                 "delivered", "snap")

    def __init__(self, sid):
        self.sid = sid
        self.highest = 0
        self.final = None
        self.reset = False
        self.stopped = False
        self.ivs = []
        self.delivered = bytearray()
        self.snap = -1


class CStore(object):
    __slots__ = ("ivs", "contig", "highest", "snap")

    def __init__(self):
        self.ivs = []
        self.contig = bytearray()
        self.highest = 0
        self.snap = -1


class Replay(object):
    def __init__(self, tid, cfg, events):
        self.id = tid
        self.cfg = cfg
        self.events = events
        self.early = cfg["early"]
        self.reject = cfg["reject"]
        self.bufmax = cfg["buffer_packets"]
        self.idle_ms = cfg["idle_ms"]
        self.msb = cfg["max_streams_bidi"]
        self.msu = cfg["max_streams_uni"]
        self.msd = cfg["max_stream_data"]
        self.max_data = cfg["max_data"]
        self.clim = cfg["crypto_limit"]
        self.sent = cfg["sent"]

        self.keys = {"I": "live", "H": "absent",
                     "Z": "live" if self.early else "absent", "A": "absent"}
        self.queue = {"I": [], "H": [], "Z": [], "A": []}
        self.qcount = 0
        self.pnsets = {"I": set(), "H": set(), "A": set()}
        self.streams = {}
        self.cs = {"I": CStore(), "H": CStore(), "A": CStore()}
        self.received_total = 0

        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0
        self.results = []

        self.txid = 0
        self.journal = []

    # ---- small helpers ---------------------------------------------------

    def res(self, ei, pi, status, reason, at, frame):
        self.results.append((ei, pi, status, reason, at, frame))

    def snapshot_stream(self, st):
        if st.snap != self.txid:
            st.snap = self.txid
            self.journal.append((0, st, st.highest, st.final, st.reset,
                                 st.stopped, len(st.delivered)))

    def snapshot_cstore(self, cs):
        if cs.snap != self.txid:
            cs.snap = self.txid
            self.journal.append((1, cs, cs.highest, len(cs.contig)))

    def get_stream(self, sid):
        st = self.streams.get(sid)
        if st is None:
            st = Stream(sid)
            self.streams[sid] = st
            self.journal.append((2, sid))
        return st

    def rollback(self, saved_total):
        j = self.journal
        for k in range(len(j) - 1, -1, -1):
            ent = j[k]
            tag = ent[0]
            if tag == 0:
                st = ent[1]
                st.highest = ent[2]
                st.final = ent[3]
                st.reset = ent[4]
                st.stopped = ent[5]
                if len(st.delivered) != ent[6]:
                    del st.delivered[ent[6]:]
            elif tag == 1:
                cs = ent[1]
                cs.highest = ent[2]
                if len(cs.contig) != ent[3]:
                    del cs.contig[ent[3]:]
            elif tag == 2:
                del self.streams[ent[1]]
            else:
                ivs = ent[1]
                i0 = ent[2]
                old = ent[4]
                ivs[i0:i0 + len(ent[3])] = old
        self.journal = []
        self.received_total = saved_total

    # ---- termination ----------------------------------------------------

    def terminate(self, state, code, at, source, peer_code):
        self.state = state
        self.code = code
        self.at_ms = at
        self.source = source
        self.peer_code = peer_code
        for lvl in LEVELS:
            self.drop_queue(lvl, "CONNECTION_CLOSED", at)

    def drop_queue(self, lvl, reason, at):
        items = self.queue[lvl]
        if not items:
            return
        self.queue[lvl] = []
        self.qcount -= len(items)
        for (ei, pi, _ta, _pkt) in items:
            self.res(ei, pi, "dropped", reason, at, None)

    # ---- events ---------------------------------------------------------

    def run(self):
        ei = 0
        for ev in self.events:
            kind = ev[0]
            t = ev[1]
            if self.state == "open" and self.idle_ms:
                deadline = self.last_activity + self.idle_ms
                if t >= deadline:
                    self.terminate("idle", "IDLE_TIMEOUT", deadline,
                                   (ei, None, None), None)
            if self.state == "open":
                if kind == "k":
                    self.do_key(ev, t)
                elif kind == "dg":
                    self.do_datagram(ei, ev)
            ei += 1
        for lvl in LEVELS:
            for (ei, pi, ta, _pkt) in self.queue[lvl]:
                self.res(ei, pi, "buffered", "NO_KEYS", ta, None)
        self.queue = {"I": [], "H": [], "Z": [], "A": []}
        self.qcount = 0

    def do_key(self, ev, t):
        lvl = ev[2]
        if ev[3] == "discard":
            self.keys[lvl] = "discarded"
            self.drop_queue(lvl, "KEYS_DISCARDED", t)
        else:
            if self.keys[lvl] == "absent":
                self.keys[lvl] = "live"
                items = self.queue[lvl]
                if items:
                    self.queue[lvl] = []
                    self.qcount -= len(items)
                    for (ei, pi, _ta, pkt) in items:
                        if self.state != "open":
                            self.res(ei, pi, "dropped", "CONNECTION_CLOSED",
                                     t, None)
                            continue
                        self.handle_packet(ei, pi, pkt, t)

    def do_datagram(self, ei, ev):
        t = ev[1]
        size = ev[2]
        pkts = ev[3]
        n = len(pkts)
        if self.state == "open":
            for pi in range(n - 1):
                if pkts[pi][0] == "A":
                    for pj in range(n):
                        self.res(ei, pj, "dropped", "LAYOUT", t, None)
                    return
        for pi in range(n):
            pkt = pkts[pi]
            if self.state != "open":
                self.res(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            lvl = pkt[0]
            if lvl == "I" and size < 1200:
                self.res(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
                continue
            if lvl == "Z" and not self.early:
                self.res(ei, pi, "dropped", "EARLY_REJECTED", t, None)
                continue
            ks = self.keys[lvl]
            if ks == "discarded":
                self.res(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
                continue
            if ks == "absent":
                if self.qcount < self.bufmax:
                    self.queue[lvl].append((ei, pi, t, pkt))
                    self.qcount += 1
                else:
                    self.res(ei, pi, "dropped", "BUFFER_FULL", t, None)
                continue
            self.handle_packet(ei, pi, pkt, t)

    # ---- packets --------------------------------------------------------

    def handle_packet(self, ei, pi, pkt, t):
        lvl, space, pn, auth, frames = pkt
        if not auth:
            self.res(ei, pi, "dropped", "AUTH", t, None)
            return
        pset = self.pnsets[space]
        if pn in pset:
            self.res(ei, pi, "duplicate", "DUPLICATE", t, None)
            return
        if not frames:
            self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", None)
            return
        fi = 0
        for fr in frames:
            if fr[0] == "un":
                self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", fi)
                return
            fi += 1
        for fi in range(len(frames)):
            tag = frames[fi][0]
            if tag not in ALLOWED or lvl not in ALLOWED[tag]:
                self.packet_error(ei, pi, t, "PROTOCOL_VIOLATION", fi)
                return
        self.txid += 1
        self.journal = []
        saved_total = self.received_total
        peer_close = None
        for fi in range(len(frames)):
            fr = frames[fi]
            tag = fr[0]
            if tag == "pad" or tag == "ping" or tag == "hd":
                continue
            if tag == "cl":
                peer_close = fr
                break
            if tag == "ack":
                err = self.frame_ack(fr, space, fi)
            elif tag == "cry":
                err = self.frame_crypto(fr, lvl)
            elif tag == "str":
                err = self.frame_stream(fr)
            elif tag == "rs":
                err = self.frame_reset(fr)
            else:  # 'ss'
                err = self.frame_stop(fr)
            if err is not None:
                code, frame = err
                self.rollback(saved_total)
                self.packet_error(ei, pi, t, code, frame)
                return
        pset.add(pn)
        self.last_activity = t
        self.res(ei, pi, "accepted", "OK", t, None)
        if peer_close is not None:
            app, code = peer_close[1], peer_close[2]
            name = ("PEER_APPLICATION_CLOSE" if app
                    else "PEER_TRANSPORT_CLOSE")
            self.terminate("closed", name, t, (ei, pi, fi_close(fr)), code)

    def packet_error(self, ei, pi, t, code, frame):
        self.res(ei, pi, "error", code, t, frame)
        self.terminate("closed", code, t, (ei, pi, frame), None)

    # ---- frames ---------------------------------------------------------

    def frame_ack(self, fr, space, fi):
        rngs = fr[1]
        if not rngs:
            return ("FRAME_ENCODING_ERROR", fi)
        prev_hi = None
        for lo, hi in rngs:
            if lo > hi:
                return ("FRAME_ENCODING_ERROR", fi)
            if prev_hi is not None and lo <= prev_hi + 1:
                return ("FRAME_ENCODING_ERROR", fi)
            prev_hi = hi
        starts, rlist = self.sent[space]
        for lo, hi in rngs:
            idx = bisect.bisect_right(starts, lo) - 1
            if idx < 0 or rlist[idx][1] < hi:
                return ("PROTOCOL_VIOLATION", fi)
        return None

    def frame_crypto(self, fr, lvl):
        off = fr[1]
        data = fr[2]
        end = off + len(data)
        if end > MAXN:
            return ("FRAME_ENCODING_ERROR", None)
        cs = self.cs[lvl]
        self.snapshot_cstore(cs)
        if end > self.clim:
            return ("CRYPTO_BUFFER_EXCEEDED", None)
        if end > cs.highest:
            cs.highest = end
        if data:
            if store_insert(cs.ivs, off, data, self.reject, self.journal) is False:
                return ("PROTOCOL_VIOLATION", None)
            chunk, _newpos = store_deliver(cs.ivs, len(cs.contig))
            if chunk:
                cs.contig += chunk
        return None

    def frame_stream(self, fr):
        sid = fr[1]
        off = fr[2]
        data = fr[3]
        fin = fr[4]
        mod = sid & 3
        if mod != 0 and mod != 2:
            return ("STREAM_STATE_ERROR", None)
        if sid // 4 + 1 > (self.msb if mod == 0 else self.msu):
            return ("STREAM_LIMIT_ERROR", None)
        st = self.get_stream(sid)
        self.snapshot_stream(st)
        end = off + len(data)
        if end > MAXN:
            return ("FRAME_ENCODING_ERROR", None)
        final = st.final
        if final is not None:
            if end > final or (fin and end != final):
                return ("FINAL_SIZE_ERROR", None)
        if fin and end < st.highest:
            return ("FINAL_SIZE_ERROR", None)
        if end > self.msd:
            return ("FLOW_CONTROL_ERROR", None)
        new_highest = end if end > st.highest else st.highest
        delta = new_highest - st.highest
        if self.received_total + delta > self.max_data:
            return ("FLOW_CONTROL_ERROR", None)
        if not st.reset:
            if data and store_insert(st.ivs, off, data, self.reject,
                                     self.journal) is False:
                return ("PROTOCOL_VIOLATION", None)
            chunk, newpos = store_deliver(st.ivs, len(st.delivered))
            if chunk:
                st.delivered += chunk
        if delta:
            st.highest = new_highest
            self.received_total += delta
        if fin:
            st.final = end
        return None

    def frame_reset(self, fr):
        sid = fr[1]
        size = fr[2]
        mod = sid & 3
        if mod != 0 and mod != 2:
            return ("STREAM_STATE_ERROR", None)
        if sid // 4 + 1 > (self.msb if mod == 0 else self.msu):
            return ("STREAM_LIMIT_ERROR", None)
        st = self.get_stream(sid)
        self.snapshot_stream(st)
        final = st.final
        if final is not None:
            if final != size:
                return ("FINAL_SIZE_ERROR", None)
        elif size < st.highest:
            return ("FINAL_SIZE_ERROR", None)
        if final is not None and size < st.highest:
            return ("FINAL_SIZE_ERROR", None)
        if size > self.msd:
            return ("FLOW_CONTROL_ERROR", None)
        new_highest = size if size > st.highest else st.highest
        delta = new_highest - st.highest
        if self.received_total + delta > self.max_data:
            return ("FLOW_CONTROL_ERROR", None)
        if delta:
            st.highest = new_highest
            self.received_total += delta
        st.final = size
        st.reset = True
        return None

    def frame_stop(self, fr):
        sid = fr[1]
        if (sid & 3) != 0:
            return ("STREAM_STATE_ERROR", None)
        if sid // 4 + 1 > self.msb:
            return ("STREAM_LIMIT_ERROR", None)
        st = self.get_stream(sid)
        self.snapshot_stream(st)
        st.stopped = True
        return None

    # ---- output ---------------------------------------------------------

    def result(self):
        pkts = []
        for (ei, pi, status, reason, at, frame) in sorted(
                self.results, key=lambda r: (r[0], r[1])):
            pkts.append({"event": ei, "packet": pi, "status": status,
                         "reason": reason, "at_ms": at,
                         "frame": frame})
        if self.state == "open":
            conn = {"state": "open", "code": None, "at_ms": None,
                    "source": None, "peer_code": None,
                    "last_activity_ms": self.last_activity}
        else:
            src = {"event": self.source[0], "packet": self.source[1],
                   "frame": self.source[2]}
            conn = {"state": self.state, "code": self.code,
                    "at_ms": self.at_ms, "source": src,
                    "peer_code": self.peer_code,
                    "last_activity_ms": self.last_activity}
        streams = []
        for sid in sorted(self.streams):
            st = self.streams[sid]
            streams.append({"id": sid, "highest": st.highest,
                            "final_size": st.final, "reset": st.reset,
                            "stopped": st.stopped,
                            "delivered_hex": bytes(st.delivered).hex()})
        crypto = []
        for lvl in ("I", "H", "A"):
            cs = self.cs[lvl]
            crypto.append({"level": lvl, "highest": cs.highest,
                           "contiguous_hex": bytes(cs.contig).hex()})
        return {"id": self.id, "packets": pkts, "connection": conn,
                "keys": {"I": self.keys["I"], "H": self.keys["H"],
                         "Z": self.keys["Z"], "A": self.keys["A"]},
                "received_total": self.received_total,
                "streams": streams, "crypto": crypto}


def fi_close(fr):
    return fr[3]


def replay_all(traces):
    results = []
    for (tid, cfg, events) in traces:
        rp = Replay(tid, cfg, events)
        rp.run()
        results.append(rp.result())
    return results


def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        text = data.decode("utf-8")
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    traces = None
    try:
        if not text or not WS_RE_OK(text):
            raise Bad()
        traces = parse_request(text)
    except (Bad, ValueError, RecursionError, MemoryError, UnicodeError,
            OverflowError, KeyError, TypeError, IndexError, AttributeError):
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        results = replay_all(traces)
        out = json.dumps({"version": 1, "results": results},
                         separators=(",", ":"))
    except Exception as exc:  # pragma: no cover - defensive
        sys.stderr.write("internal error: %r\n" % (exc,))
        sys.stdout.write(INVALID_OUT)
        return 0
    sys.stdout.write(out)
    return 0


def WS_RE_OK(text):
    """Reject trailing content after the single JSON document."""
    i = 0
    n = len(text)
    while i < n and text[i] in JSON_WS:
        i += 1
    dec = DECODER
    obj, end = dec.raw_decode(text, i)
    while end < n and text[end] in JSON_WS:
        end += 1
    if end != n:
        raise Bad()
    # re-bind the parsed object so parse_request does not re-parse
    WS_RE_OK.obj = obj
    return True


if __name__ == "__main__":
    sys.exit(main())
